"""Header-only orientation and export size checks, using generated byte fixtures."""
from pathlib import Path
import struct
import sys
import tempfile
import unittest

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from image_metadata import image_metadata, _orientation, HEADER_LIMIT
from demo_data import generate_demo


def exif(orientation):
    return b'II' + struct.pack('<HIH',42,8,1) + struct.pack('<HHIHHI',274,3,1,orientation,0,0)


class MetadataTests(unittest.TestCase):
    def setUp(self):
        parent=ROOT/'local'/'test-tmp';parent.mkdir(parents=True,exist_ok=True)
        self.temp=tempfile.TemporaryDirectory(dir=str(parent));self.addCleanup(self.temp.cleanup)
        self.root=Path(self.temp.name)

    def test_png_dimensions_are_real_not_layout_guesses(self):
        config=generate_demo(self.root/'demo',count=2)
        folder=Path(config['methods'][0]['root'])
        self.assertEqual(image_metadata(folder/'scene-0001.png')['width'],320)
        self.assertEqual(image_metadata(folder/'scene-0002.png')['height'],256)

    def test_exif_rotated_jpeg_swaps_export_dimensions(self):
        for orientation in range(1,9):
            payload=b'Exif\0\0'+exif(orientation)
            data=b'\xff\xd8\xff\xe1'+struct.pack('>H',len(payload)+2)+payload
            data+=b'\xff\xc0'+struct.pack('>H',8)+b'\x08'+struct.pack('>HH',16,32)+b'\x00'
            path=self.root/('rotated-'+str(orientation)+'.jpg');path.write_bytes(data)
            metadata=image_metadata(path)
            self.assertEqual(metadata['orientation'],orientation)
            self.assertEqual((metadata['width'],metadata['height']),(16,32) if orientation>=5 else (32,16))

    def test_corrupt_exif_is_bounded_and_not_an_exception(self):
        data=b'\xff\xd8\xff\xe1\x00\x0eExif\0\0II\x2a\x00\xff\xff'
        self.assertEqual(_orientation(data),1)
        self.assertEqual(HEADER_LIMIT,262144)

    def test_unrecognized_bytes_return_no_geometry(self):
        path=self.root/'broken.png';path.write_bytes(b'not an image')
        self.assertIsNone(image_metadata(path))


if __name__=='__main__':unittest.main()
